// This is start of the header guard. By convention, we use the name of the header file.

#ifndef CGAL_SEARCH_WITH_POINT_H
#define MAKE_SURFACE_MESH_H
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Search_traits_3.h>
#include <CGAL/Search_traits_adapter.h>
#include <CGAL/point_generators_3.h>
#include <CGAL/Orthogonal_k_neighbor_search.h>
#include <CGAL/property_map.h>
#include <boost/iterator/zip_iterator.hpp>
#include <utility>

typedef CGAL::Exact_predicates_inexact_constructions_kernel Kernel;
typedef Kernel::Point_3                                     Point_3;
typedef boost::tuple<Point_3,int>                           Point_and_int;
typedef CGAL::Random_points_in_cube_3<Point_3>              Random_points_iterator;
typedef CGAL::Search_traits_3<Kernel>                       Traits_base;
typedef CGAL::Search_traits_adapter<Point_and_int,
  CGAL::Nth_of_tuple_property_map<0, Point_and_int>,
  Traits_base>                                              Traits;
typedef CGAL::Orthogonal_k_neighbor_search<Traits>          K_neighbor_search;
typedef K_neighbor_search::Tree                             Tree;
typedef K_neighbor_search::Distance                         Distance;


class cgal_search_with_point{

public:
	cgal_search_with_point();
	~cgal_search_with_point();

	// initialize
	int initialize();

	// add point with id
	int addPoint(const int id, const double x, const double y, const double z);

	// make data points tree
	int makeTree();

	// search closest points
	int searchClosestPoints(const int K, const double x, const double y, const double z,
			std::vector<int> &ids);

	// search closest points
	int searchClosestPoints2(const int K, const double x, const double y, const double z, int ids[]);

	// search closest point
	int searchClosestPoint(const double x, const double y, const double z,int &id);

	// clear data points tree
	int clearTree();

	// clear data points
	int clearPoints();

	// clear search indes
	int clearSearch();

	// clear data points and tree
	int clearAll();

protected:

private:
	// 3D points vector
	std::vector<Point_3> points;

	// 3D points indices, this is corresponding to the point index in vtk file
	std::vector<int> indices;

	// temporary indices, bridge between C++ and Fortran
	std::vector<int> ids_c_f;

	// Data points tree
	Tree pointTree;

};

// This is the end of the header guard
#endif
